import React, {} from "react";
import { ElementsConsumer,  PaymentElement } from "@stripe/react-stripe-js";
import { message } from "antd";
import { withRouter } from "react-router-dom";
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import {
    handleQuizStripeModal,
    makeStripePayment
} from "../Container/Quiz/QuizAction";
import "./MainApp.scss";


class QuizCheckoutForm extends React.Component {
 
  handleSubmit = async (event) => {
    event.preventDefault();
    const { stripe, elements } = this.props;

    if (!stripe || !elements) {

      return;
    }
    const result = await stripe.confirmPayment({
      elements, 
      
      confirmParams: {
         return_url: `http://host.quizledge.no/drb/payloadinginside/${this.props.stripePaymentId}/${this.props.paymentId}/${this.props.eachSub.subscriptionId}/${this.props.eachSub.userId}` //Quiweb
        // return_url: `http://localhost:3000/drb/payloadinginside/${this.props.stripePaymentId}/${this.props.paymentId}/${this.props.eachSub.subscriptionId}/${this.props.eachSub.userId}` // localhostD
      },
    });

    if (result.error) {
      message.error(result.error.message)
      this.props.handleQuizStripeModal(false)
      console.log(result.error.message);
    } else {
   
    }
  }; 

  render() {
    const { stripe } = this.props;

    console.log(this.props.eachSub) 

    return (
      <form onSubmit={this.handleSubmit}>
<PaymentElement/>
        <button
          type="submit"
          disabled={!stripe}
          className="StripePayButton"
        >
            {`Pay ${this.props.eachSub.pricePerMonth} ${"EUR"}`}
        </button>
      </form>
    );
  }
}

function QuizsCheckoutForm(props) {

  return (
    <ElementsConsumer>
      {({ stripe, elements }) => (
        <QuizCheckoutForm
          stripe={stripe}
          elements={elements}
          paymentId={props.paymentId}
          stripePaymentId={props.stripePaymentId}
          addiNVEStripeModal={props.addiNVEStripeModal}
          handleQuizStripeModal={props.handleQuizStripeModal}
          finalgrandTotalValue={"100"}
          confirmedQuizPayment={props.confirmedQuizPayment}
          currency={"EUR"}
          eachSub={props.eachSub}
         
        />
      )}
    </ElementsConsumer>
  );
}
const mapStateToProps = ({  quiz }) => ({
  confirmedQuizPayment: quiz.confirmedQuizPayment,
  paymentId: quiz.paymentQuizDetails.paymentId,
  stripePaymentId: quiz.paymentQuizDetails.stripePaymentId,
  addiNVEStripeModal: quiz.addiNVEStripeModal,
});
const mapDispatchToProps = (dispatch) =>
  bindActionCreators(
    {
       makeStripePayment,
      handleQuizStripeModal,
    },
    dispatch
  );
export default withRouter(
  connect(mapStateToProps, mapDispatchToProps)(QuizsCheckoutForm)
);
